  </div>

  <!-- Etapa 2 -->
  <div class="question-box" data-step="2">
   <p class="question-text">PERGUNTA 2: QUAL É O SEU PRINCIPAL OBJETIVO AO USAR NOSSOS PRODUTOS?</p>
   <div class="options">
    <div class="option" onclick="selectOption(this, 2, 1)">💪 Melhorar a saúde e o bem-estar</div>
