    <div class="option" onclick="selectOption(this, 2, 4)">🎯 Alcançar metas pessoais específicas</div>
   </div>
   <button class="next-btn" onclick="checkAnswer(2)" id="btn2">PRÓXIMA ETAPA →</button>
  </div>

  <!-- Etapa 3 -->
  <div class="question-box" data-step="3">
   <p class="question-text">PERGUNTA 3: QUANTO TEMPO VOCÊ DEDICA POR DIA PARA SEU DESENVOLVIMENTO?</p>
   <div class="options">
    <div class="option" onclick="selectOption(this, 3, 1)">⏰ Menos de 30 minutos</div>
    <div class="option" onclick="selectOption(this, 3, 2)">⏰ 30 a 60 minutos</div>
    <div class="option" onclick="selectOption(this, 3, 3)">⏰ 1 a 2 horas</div>
    <div class="option" onclick="selectOption(this, 3, 4)">⏰ Mais de 2 horas</div>
   </div>
   <button class="next-btn" onclick="checkAnswer(3)" id="btn3">PRÓXIMA ETAPA →</button>
  </div>

  <!-- Etapa 4 -->
  <div class="question-box" data-step="4">
   <p class="question-text">PERGUNTA 4: QUAL A PRINCIPAL BARREIRA QUE VOCÊ ENCONTRA PARA MUDANÇAS?</p>
   <div class="options">
    <div class="option" onclick="selectOption(this, 4, 1)">⏳ Falta de tempo</div>
    <div class="option" onclick="selectOption(this, 4, 2)">😴 Cansaço mental</div>
    <div class="option" onclick="selectOption(this, 4, 3)">🤔 Dúvida sobre o método</div>
    <div class="option" onclick="selectOption(this, 4, 4)">🚫 Falta de motivação</div>
   </div>
   <button class="next-btn" onclick="checkAnswer(4)" id="btn4">PRÓXIMA ETAPA →</button>
  </div>

  <!-- Etapa 5: VSL + Compra -->
  <div class="vsl-screen" id="vsl-screen">
   <h2 style="font-family:'Helvetica Neue',Helvetica,Arial,sans-serif; font-weight:700; margin-bottom:10px;">VEJA SEU VÍDEO DE VENDAS (VSL)</h2>
